-- INFO: Create Schema
DROP SCHEMA IF EXISTS received_order CASCADE;
CREATE SCHEMA received_order;

-- INFO: Create Type Enum
CREATE TYPE received_order.order_status AS enum (
  'PREPARING',
  'IN_PROGRESS',
  'CANCELED',
  'COMPLETED'
);

